-- =====================================================================
-- Mise à jour n°15 du 13/11/2026 : Parcours IA Webmaster proposé à deux nouveaux publics
--   1. Sous-profil « Auto-entrepreneur, indépendant(e) » (ia-004) : ajout du Parcours IA Webmaster
--      en 2e parcours, avec son « Pourquoi », ses arguments par module et son argumentaire détaillé.
--   2. Nouveau sous-profil « Assistant(e) commercial(e) » (ia-033), famille Administratif et commercial :
--      Parcours IA Administratif & commercial puis Parcours IA Webmaster, avec leurs arguments.
-- À coller dans Supabase › SQL Editor › New query, puis « Run ». Ne touche à rien d'autre. Le relancer ne change rien.
-- =====================================================================
update public.profils set data = jsonb_set(data, '{parcours}', coalesce(data->'parcours', '[]'::jsonb) || jsonb_build_array($j${"formation": "ia-webmaster", "pourquoi": "Si son site internet doit lui amener des clients.", "reponses": {"M2": "Pages de services et articles rédigés avec l'IA, optimisés pour Google et pour les réponses des IA : son site travaille pour lui ou pour elle.", "M3": "Visuels et voix off pour habiller son site et ses publications, sans passer par un prestataire."}, "argumentaire": "Pour l'indépendant(e) qui a un site ou veut en tirer davantage : le M2 lui apprend à rédiger avec l'IA des pages et articles visibles sur Google et dans les réponses des IA (GEO-SEO) ; le M3 à créer seul(e) visuels et voix off. Résultat : plus de visibilité et de demandes de contact, sans budget d'agence."}$j$::jsonb)), updated_at = now()
where id = 'ia-004' and not exists (select 1 from jsonb_array_elements(coalesce(data->'parcours', '[]'::jsonb)) x where x->>'formation' = 'ia-webmaster');

insert into public.profils (id, data, updated_at) values ('ia-033', $j${"nom": "Assistant(e) commercial(e)", "domaine": "ia", "categorie": "Administratif et commercial", "categories": ["Administratif et commercial"], "ordre": 33, "besoin": "Gagner du temps sur les devis, les relances et les contenus commerciaux.", "besoinDetail": {"situation": "Prépare devis et propositions, assure le suivi et les relances clients, met à jour fiches produits, catalogues, parfois le site ou la newsletter.", "difficulte": "Beaucoup d'écrits répétitifs et de contenus commerciaux à produire vite, sans être rédacteur(trice) ni graphiste.", "attente": "Produire plus vite des écrits commerciaux soignés et des contenus qui valorisent l'offre, en ligne comme sur papier."}, "motsCles": "assistant commercial, assistante commerciale, assistant(e) commercial(e), assistant des ventes, devis, relances, propositions commerciales, fiches produits, catalogue, newsletter, site internet, e-commerce, ChatGPT", "reponses": {"M1": "Comprendre le fonctionnement de l'IA générative, rédiger des prompts efficaces, comparer les outils (ChatGPT, Mistral, Gemini, Claude…) et adopter les bons réflexes : limites, éthique et sécurité des données."}, "parcours": [{"formation": "ia-admin", "pourquoi": "Devis, relances et suivi clients au quotidien.", "reponses": {"M2": "Devis, propositions, relances et mails clients : des modèles réutilisables et un agent personnalisé qui connaît l'offre et les tarifs.", "M3": "Visuels et contenus audio pour présenter les offres et animer la relation client."}, "argumentaire": "Le M2 traite le cœur du poste : devis, propositions commerciales, relances et mails clients, avec un assistant personnalisé qui connaît l'offre et les tarifs ; le M3 ajoute visuels et supports de présentation. Résultat : moins de temps sur l'écrit, plus de temps pour les clients."}, {"formation": "ia-webmaster", "pourquoi": "Si la personne gère aussi le site, les fiches produits ou la newsletter.", "reponses": {"M2": "Fiches produits, pages d'offre et articles rédigés avec l'IA, optimisés pour Google et pour les réponses des IA.", "M3": "Visuels et voix off pour mettre en valeur produits et offres en ligne."}, "argumentaire": "Pour l'assistant(e) commercial(e) qui alimente le site, l'e-boutique ou la newsletter : le M2 lui apprend à rédiger avec l'IA des fiches produits et pages d'offre visibles sur Google et dans les IA (GEO-SEO) ; le M3 à créer visuels et voix off. Résultat : une offre mieux présentée en ligne, publiée plus vite."}], "complements": [{"formation": "com-canva1", "pourquoi": "Créer ses visuels commerciaux soi-même, sans compétences graphiques."}]}$j$::jsonb, now())
on conflict (id) do nothing;

-- Vérification : les deux sous-profils et leurs parcours
select id, data->>'nom' as sous_profil, (select string_agg(x->>'formation', ' puis ' order by o) from jsonb_array_elements(data->'parcours') with ordinality t(x, o)) as parcours
from public.profils where id in ('ia-004', 'ia-033') order by id;
